import re
class P:
    def __init__(self):
        self.pat = re.compile(r"\d+")
    def all(self, s):
        return self.pat.findall(s)
p = P()
print(p.all("a1b22"))

import re
class P:
    def __init__(self):
        self.pat = re.compile(r"(\d+)")
    def first(self, s):
        m = self.pat.search(s)
        return m.group(1)
p = P()
print(p.first("x42y"))

import re
class P:
    def __init__(self, s):
        self.s = s
    def run(self):
        return re.search(r"\d+", self.s)
p = P("x7y")
print(p.run())

import re
class P:
    def __init__(self):
        self.pat = re.compile(r"(\w+)=(\w+)")
    def first(self, text):
        pat = self.pat
        m = pat.search(text)
        return m.group(1)
p = P()
print(p.first("color=red"))
